import { afterEach, describe, expect, test } from "bun:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { batchSignature, lastRunFromLog } from "./batch";
import { memoryPhone } from "./phone";
import { DEFAULT_RULES, proposeBatch, seoulToday, summarize } from "./rules";
import { MacroStore } from "./store";

const stores: MacroStore[] = [];

function open(connected = true) {
	const phone = memoryPhone({ connected });
	const store = new MacroStore(":memory:", phone);
	stores.push(store);
	return { store, phone };
}

afterEach(() => {
	while (stores.length > 0) stores.pop()?.close();
});

describe("시드", () => {
	test("판매중 12개를 넣고 기본 제안은 끌어올리기 6·가격만 1이다(관심이 3개 미만인 글은 가격 내리기를 미룬다)", () => {
		const { store } = open();
		const listings = store.listings();
		expect(listings).toHaveLength(12);
		const summary = summarize(proposeBatch(listings, DEFAULT_RULES));
		expect(summary).toEqual({ bump: 6, priceOnly: 1, skip: 5, held: 5 });
		expect(store.activeBatch()).toBeNull();
		expect(store.settings().runHour).toBe(19);
		expect(store.settings().runMinute).toBe(0);
		expect(store.settings()).toMatchObject({ dailyLimit: 6, minHearts: 3, heartGrowthPct: 20 });
	});

	test("끌올 횟수·시각은 문구에서 남기고 다음 시각은 추정표로 채운다", () => {
		const { store } = open();
		const ac = store.listings().find((listing) => listing.id === "ac");
		expect(ac?.bumpCount).toBe(7);
		expect(ac?.bumpedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
		const bumped = Date.parse(ac?.bumpedAt ?? "");
		const next = Date.parse(ac?.nextBumpAt ?? "");
		// 3회 이후는 96시간.
		expect(next - bumped).toBe(96 * 3_600_000);
	});
});

describe("실행 목록", () => {
	test("지금 글·설정으로 바로 만들고 저장하지 않는다", () => {
		const { store } = open();
		// 실행기(`fulfillOnce`)는 Date를 넘긴다.
		const now = new Date(`${seoulToday()}T19:00:00+09:00`);
		const batch = store.currentBatch(now);
		// 시드의 시작일이 오늘이라, 시계를 오늘로 맞춰야 직선이 시작한 뒤의 제안이 나온다.
		const summary = summarize(proposeBatch(store.listings(), DEFAULT_RULES, seoulToday(), now));
		expect(batch.status).toBe("approved");
		expect(batch.items).toHaveLength(summary.bump + summary.priceOnly);
		expect(batch.runHour).toBe(19);
		expect(batch.runMinute).toBe(0);
		expect(batch.signature).toBe(store.signature());
		expect(store.activeBatch()).toBeNull();
	});

	test("승인 배치와 같은 글을 고른다", () => {
		const { store } = open();
		// 두 길 모두 같은 시계를 쓴다. 실행은 승인 없이 `currentBatch`를 그대로 쓴다.
		const items = store.currentBatch().items.map((item) => [item.id, item.action, item.proposedPrice]);
		const approved = store.approve().batch.items.map((item) => [item.id, item.action, item.proposedPrice]);
		expect(items).toEqual(approved);
	});

	test("콜타임인 글은 실행 목록에서 빠진다", () => {
		const { store } = open();
		store.recordCooldown("shelf", new Date(Date.now() + 12 * 3_600_000).toISOString());
		const batch = store.currentBatch();
		expect(batch.items.some((item) => item.id === "shelf")).toBe(false);
		// 빠진 자리는 다음 순번이 채우고, 하루 한도는 여전히 6개다.
		expect(batch.items.filter((item) => item.action === "bump")).toHaveLength(6);
	});

	test("폰에서 예약중으로 확인된 글은 실행 목록에서 빠지고 화면에 예약중으로 남는다", () => {
		const { store } = open();
		store.recordReserved("shelf");
		expect(store.currentBatch().items.some((item) => item.id === "shelf")).toBe(false);
		expect(store.listings().find((row) => row.id === "shelf")?.reserved).toBe(true);
	});

	test("끌올 하나를 마치면 횟수·마지막 시각·다음 시각을 남긴다", () => {
		const { store } = open();
		const at = "2026-10-28T10:00:00.000Z";
		store.recordBump("shelf", { bumpedAt: at });
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpCount).toBe(1);
		expect(shelf?.bumpedAt).toBe(at);
		expect(Date.parse(shelf?.nextBumpAt ?? "") - Date.parse(at)).toBe(60 * 3_600_000);
	});

	test("폰 남은 시간을 알려 주면 다음 시각은 관측값을 따른다", () => {
		const { store } = open();
		const at = "2026-10-28T10:00:00.000Z";
		const observed = "2026-11-05T10:00:00.000Z";
		store.recordBump("shelf", { bumpedAt: at, bumpCount: 4, nextBumpAt: observed });
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpCount).toBe(4);
		expect(shelf?.nextBumpAt).toBe(observed);
	});

	test("끌올 횟수의 지금 값은 모르면 0이다", () => {
		const { store } = open();
		expect(store.previousBumpCount("shelf")).toBe(0);
		store.recordBump("shelf", { bumpedAt: "2026-10-28T10:00:00.000Z" });
		expect(store.previousBumpCount("shelf")).toBe(1);
	});

	test("다음 시각만 관측값으로 바꿀 수 있다", () => {
		const { store } = open();
		const observed = new Date(Date.now() + 30 * 60_000).toISOString();
		store.recordCooldown("desk", observed);
		const desk = store.listings().find((listing) => listing.id === "desk");
		expect(desk?.nextBumpAt).toBe(observed);
		expect(desk?.bumpCount).toBeNull();
	});
});

