		const { store } = open();
		const row = store.listings()[0];
		store.saveListing(row.id, { target: row.price - 5_000, until: "2026-12-31" }, "2026-11-01");
		const anchored = store.listings()[0];
		expect(anchored.startPrice).toBe(row.price);
		expect(anchored.startDate).toBe("2026-11-01");
		store.saveListing(row.id, { included: false }, "2026-11-05");
		expect(store.listings()[0].startDate).toBe("2026-11-01");
		store.saveListing(row.id, { until: "2026-12-30" }, "2026-11-05");
		expect(store.listings()[0].startDate).toBe("2026-11-05");
		store.saveListing(row.id, { target: null }, "2026-11-06");
