							? current.price
							: (current.startPrice ?? null),
				":start_date": keptDate,
			});
		return null;
	}

	/** 고른 글들의 마감일을 한 번에 바꾼다. 글마다 `saveListing`과 같은 규칙으로 직선을 새로 긋는다. */
	saveUntilMany(ids: string[], until: string, today = seoulToday()) {
		for (const id of ids) this.saveListing(id, { until }, today);
	}

	settings(): ScreenSettings {
		const rows = this.db.prepare(`SELECT key, value FROM setting`).all() as { key: string; value: string }[];
		const map = new Map(rows.map((row) => [row.key, row.value]));
		const number = (key: string, fallback: number) => {
			const raw = map.get(key);
			if (raw === undefined) return fallback;
			const value = Number(raw);
			return Number.isFinite(value) ? value : fallback;
		};
		return {
			dailyLimit: number("dailyLimit", DEFAULT_RULES.dailyLimit),
			minHearts: number("minHearts", DEFAULT_RULES.minHearts),
			heartGrowthPct: number("heartGrowthPct", DEFAULT_RULES.heartGrowthPct),
			runHour: number("runHour", DEFAULT_SETTINGS.runHour),
			runMinute: number("runMinute", DEFAULT_SETTINGS.runMinute),
		};
	}

	saveSettings(settings: ScreenSettings) {
		const upsert = this.db.prepare(
			`INSERT INTO setting(key, value) VALUES (:key, :value)
			ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
		);
		for (const [key, value] of Object.entries(settings)) {
			upsert.run({ ":key": key, ":value": String(value) });
		}
	}

	slot(): { day: string | null; status: SlotStatus | null } {
		const row = this.db.prepare(`SELECT day, status FROM due_slot WHERE id = 1`).get() as
			{ day: string; status: string } | undefined;
		if (!row) return { day: null, status: null };
		if (row.status !== "ran" && row.status !== "skipped" && row.status !== "waiting") {
			return { day: row.day, status: null };
		}
		return { day: row.day, status: row.status };
	}

	saveSlot(day: string, status: SlotStatus) {
		this.db
			.prepare(
				`INSERT INTO due_slot(id, day, status) VALUES (1, :day, :status)
				 ON CONFLICT(id) DO UPDATE SET day = excluded.day, status = excluded.status`,
			)
			.run({ ":day": day, ":status": status });
	}

	lastRun(): LastRun {
		const row = this.db.prepare(`SELECT at, bumped, priced_only, skipped, note FROM last_run WHERE id = 1`).get() as
			{ at: string; bumped: number; priced_only: number; skipped: number; note: string } | undefined;
		if (!row) {
			return { at: "", bumped: 0, pricedOnly: 0, skipped: 0, note: "" };
		}
		return {
			at: row.at,
			bumped: row.bumped,
			pricedOnly: row.priced_only,
			skipped: row.skipped,
			note: row.note,
		};
	}

	activeBatch(): BatchFile | null {
		const gate = this.executionBatch();
		return gate.status === "approved" ? gate.batch : null;
	}

	/** 마지막 배치. 취소는 payload가 아니라 status 열을 따른다. */
	executionBatch(): { status: "none" | "approved" | "cancelled"; batch: BatchFile | null } {
		const row = this.db
			.prepare(`SELECT payload, status FROM batch ORDER BY created_at DESC, rowid DESC LIMIT 1`)
			.get() as { payload: string; status: string } | undefined;
		if (!row) return { status: "none", batch: null };
		const batch = JSON.parse(row.payload) as BatchFile;
		if (row.status === "cancelled") return { status: "cancelled", batch: { ...batch, status: "cancelled" } };
		if (row.status === "approved") return { status: "approved", batch };
		return { status: "none", batch: null };
	}

	signature(): string {
		return batchSignature(this.listings(), this.settings());
	}

	/**
	 * 지금 글과 설정으로 만드는 실행 목록. 저장하지 않는다.
	 * 실행은 승인 없이 이 값을 그대로 쓴다.
	 */
	currentBatch(now: number | Date = Date.now()): BatchFile {
		const at = now instanceof Date ? now.getTime() : now;
		const listings = this.listings();
		const settings = this.settings();
		const rules: RuleSet = {
			dailyLimit: settings.dailyLimit,
			minHearts: settings.minHearts,
			heartGrowthPct: settings.heartGrowthPct,
		};
		const proposals = proposeBatch(listings, rules, seoulToday(at), at);
		return {
			id: uuidv7(),
			status: "approved",
			signature: batchSignature(listings, settings),
			runHour: settings.runHour,
			runMinute: settings.runMinute,
			items: itemsFromProposals(listings, proposals),
			approvedAt: new Date(at).toISOString(),
		};
	}

	/** 지금까지 끌어올린 횟수. 모르면 0. */
	previousBumpCount(listingId: string): number {
		const row = this.db.prepare(`SELECT bump_count FROM listing WHERE id = :id`).get({ ":id": listingId }) as
			{ bump_count: number | null } | undefined;
		return row?.bump_count ?? 0;
	}

	/** 실행이 끌올 하나를 마쳤을 때. 횟수를 안 주면 지금 값 + 1, 다음 시각을 안 주면 추정표를 쓴다. */
	recordBump(
		listingId: string,
		bump: { bumpedAt: string; bumpCount?: number | null; nextBumpAt?: string | null },
	): void {
		const row = this.listings().find((listing) => listing.id === listingId);
		if (!row) return;
		const bumpCount = bump.bumpCount ?? (row.bumpCount ?? 0) + 1;
		const next = bump.nextBumpAt ?? estimateNextBumpAt(bump.bumpedAt, bumpCount);
		this.db
			.prepare(
				`UPDATE listing SET bumped_at = :bumped_at, bump_count = :bump_count, next_bump_at = :next_bump_at
				 WHERE id = :id`,
			)
			.run({
				":id": listingId,
				":bumped_at": bump.bumpedAt,
				":bump_count": bumpCount,
				":next_bump_at": next,
			});
	}

	/** 폰에 뜬 남은 시간을 그대로 남긴다. 관측값은 추정을 이긴다. */
	recordCooldown(listingId: string, next: string): void {
		this.db.prepare(`UPDATE listing SET next_bump_at = :next WHERE id = :id`).run({
			":id": listingId,
			":next": next,
		});
	}

	recordReserved(listingId: string): void {
		this.db.prepare(`UPDATE listing SET reserved = 1 WHERE id = :id`).run({ ":id": listingId });
	}

	approve(): ApproveResult {
		const batch = this.currentBatch();
		this.db
			.prepare(
				`INSERT INTO batch(id, status, signature, payload, phone_ok, phone_error, created_at)
				 VALUES (:id, :status, :signature, :payload, :phone_ok, :phone_error, :created_at)`,
			)
			.run({
				":id": batch.id,
				":status": "approved",
				":signature": batch.signature,
				":payload": JSON.stringify(batch),
				":phone_ok": 1,
				":phone_error": null,
				":created_at": batch.approvedAt,
			});
		return { batch, phone: { ok: true }, phoneFileExists: false };
	}

	cancel(): CancelResult {
		const active = this.activeBatch();
		if (!active) {
			return { status: "cancelled", phone: { ok: true }, phoneFileExists: false, notice: null };
		}
		const hadFile = this.phone.exists();
		const phone = this.phone.remove();
		this.db.prepare(`UPDATE batch SET status = 'cancelled' WHERE id = :id`).run({ ":id": active.id });
		const leftover = !phone.ok && hadFile;
		return {
			status: "cancelled",
			phone: leftover ? phone : { ok: true },
			phoneFileExists: leftover,
			notice: leftover ? NOTICE_UNDELIVERED : null,
		};
	}

	private migrate() {
		this.db.exec(`
			CREATE TABLE IF NOT EXISTS listing (
				id TEXT PRIMARY KEY,
				title TEXT NOT NULL,
				price INTEGER NOT NULL,
				hearts INTEGER NOT NULL,
				views INTEGER NOT NULL,
				chats INTEGER NOT NULL,
				area TEXT NOT NULL,
				posted_ago_days INTEGER,
				bump_ago_days INTEGER,
				bump_count INTEGER,
				bumped_at TEXT,
				next_bump_at TEXT,
				reserved INTEGER NOT NULL DEFAULT 0,
				floor INTEGER,
				included INTEGER NOT NULL,
				ratio INTEGER,
				target INTEGER,
				until TEXT,
				photo TEXT,
				start_price INTEGER,
				start_date TEXT,
				cut_hearts INTEGER
			);
			CREATE TABLE IF NOT EXISTS setting (
				key TEXT PRIMARY KEY,
				value TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS batch (
				id TEXT PRIMARY KEY,
				status TEXT NOT NULL,
				signature TEXT NOT NULL,
				payload TEXT NOT NULL,
				phone_ok INTEGER NOT NULL,
				phone_error TEXT,
				created_at TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS last_run (
				id INTEGER PRIMARY KEY CHECK (id = 1),
				at TEXT NOT NULL,
				bumped INTEGER NOT NULL,
				priced_only INTEGER NOT NULL,
				skipped INTEGER NOT NULL,
				note TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS sync (
				id INTEGER PRIMARY KEY CHECK (id = 1),
				at TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS due_slot (
				id INTEGER PRIMARY KEY CHECK (id = 1),
				day TEXT NOT NULL,
				status TEXT NOT NULL
			);
		`);
	}

	private seedIfEmpty() {
		const count = (this.db.prepare(`SELECT COUNT(*) AS n FROM listing`).get() as { n: number } | undefined)?.n ?? 0;
		if (count > 0) return;
		const insert = this.db.prepare(
			`INSERT INTO listing(id, title, price, hearts, views, chats, area, posted_ago_days, bump_ago_days, bump_count, bumped_at, next_bump_at, included, target, until, photo)
			 VALUES (:id, :title, :price, :hearts, :views, :chats, :area, :posted_ago_days, :bump_ago_days, :bump_count, :bumped_at, :next_bump_at, :included, :target, :until, :photo)`,
		);
		// 시드는 지금 시각에서 `끌올 N일 전`을 되짚어 쓰고, 다음 시각은 추정표로 채운다.
		const now = Date.now();
		this.transact(() => {
			for (const post of seed.posts) {
				const bumpedAt = post.bumpAgoDays === null ? null : new Date(now - post.bumpAgoDays * 86_400_000).toISOString();
				insert.run({
					":id": post.id,
					":title": post.title,
					":price": post.price,
					":hearts": post.hearts,
					":views": post.views,
					":chats": post.chats,
					":area": post.area,
					":posted_ago_days": post.postedAgoDays,
					":bump_ago_days": post.bumpAgoDays,
					":bump_count": post.bumpCount ?? null,
					":bumped_at": bumpedAt,
					":next_bump_at": bumpedAt === null || !post.bumpCount ? null : estimateNextBumpAt(bumpedAt, post.bumpCount),
					":included": post.included ? 1 : 0,
					":target": post.target,
					":until": post.until,
					":photo": null,
				});
			}
			const upsert = this.db.prepare(
				`INSERT INTO setting(key, value) VALUES (:key, :value) ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
			);
			for (const [key, value] of Object.entries(DEFAULT_SETTINGS)) {
				upsert.run({ ":key": key, ":value": String(value) });
			}
			this.db
				.prepare(
					`INSERT INTO last_run(id, at, bumped, priced_only, skipped, note)
					 VALUES (1, :at, :bumped, :priced_only, :skipped, :note)`,
				)
				.run({
					":at": seed.lastRun.at,
					":bumped": seed.lastRun.bumped,
					":priced_only": seed.lastRun.pricedOnly,
					":skipped": seed.lastRun.skipped,
					":note": seed.lastRun.note,
				});
		});
	}

	private ensurePhotoColumn() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		if (cols.some((col) => col.name === "photo")) return;
		this.db.exec("ALTER TABLE listing ADD COLUMN photo TEXT");
	}

	/** 끌올 횟수·마지막 시각·다음 가능 시각. 옛 DB는 칸을 더한다. */
	ensureBumpColumns() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		const names = new Set(cols.map((col) => col.name));
		if (!names.has("bump_count")) this.db.exec("ALTER TABLE listing ADD COLUMN bump_count INTEGER");
		if (!names.has("bumped_at")) this.db.exec("ALTER TABLE listing ADD COLUMN bumped_at TEXT");
		if (!names.has("next_bump_at")) this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_at TEXT");
		if (!names.has("reserved")) this.db.exec("ALTER TABLE listing ADD COLUMN reserved INTEGER NOT NULL DEFAULT 0");
		// 칸이 생기기 전에 읽은 글은 '끌올 N일 전' 으로 마지막 끌올을 어림한다. 다음 새로 읽기가 덮는다.
		this.db.exec(
			`UPDATE listing SET bumped_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-' || bump_ago_days || ' days')
			 WHERE bumped_at IS NULL AND bump_ago_days IS NOT NULL`,
		);
	}

	/** 마지막 인하 때의 관심 수. 옛 DB는 칸을 더한다. */
	private ensureCutColumn() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		if (cols.some((col) => col.name === "cut_hearts")) return;
		this.db.exec("ALTER TABLE listing ADD COLUMN cut_hearts INTEGER");
	}

	/** 예전 기본값(아침 8시 5분)으로 저장된 회차는 저녁 19:00으로 옮긴다. */
	private moveToEvening() {
		this.db
			.prepare(`UPDATE setting SET value = :hour WHERE key = 'runHour' AND value = '8'`)
			.run({ ":hour": String(DEFAULT_SETTINGS.runHour) });
		this.db
			.prepare(`UPDATE setting SET value = :minute WHERE key = 'runMinute' AND value = '5'`)
			.run({ ":minute": String(DEFAULT_SETTINGS.runMinute) });
	}

	ensureScheduleColumns() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		const names = new Set(cols.map((col) => col.name));
		if (!names.has("target")) {
			this.db.exec("ALTER TABLE listing ADD COLUMN target INTEGER");
			this.db.exec("UPDATE listing SET target = floor WHERE floor IS NOT NULL");
		}
		if (!names.has("until")) this.db.exec("ALTER TABLE listing ADD COLUMN until TEXT");
		if (!names.has("start_price")) this.db.exec("ALTER TABLE listing ADD COLUMN start_price INTEGER");
		if (!names.has("start_date")) this.db.exec("ALTER TABLE listing ADD COLUMN start_date TEXT");
		this.fillStartPrices();
	}

	/** 시작가가 없던 일정은 처음 열린 날의 가격에서 직선을 시작한다. */
	private fillStartPrices() {
		this.db
			.prepare(
				`UPDATE listing SET start_price = price, start_date = :today
				 WHERE target IS NOT NULL AND until IS NOT NULL AND start_price IS NULL`,
			)
			.run({ ":today": seoulToday() });
	}

	private transact(fn: () => void) {
		this.db.exec("BEGIN");
		try {
			fn();
			this.db.exec("COMMIT");
		} catch (error) {
			this.db.exec("ROLLBACK");
			throw error;
		}
	}
}

function fromRow(row: ListingRow): ScreenListing {
	return {
		id: row.id,
		title: row.title,
		price: row.price,
		hearts: row.hearts,
		views: row.views,
		chats: row.chats,
		area: row.area,
		postedAgoDays: row.posted_ago_days,
		bumpAgoDays: row.bump_ago_days,
		bumpCount: row.bump_count,
		bumpedAt: row.bumped_at,
		nextBumpAt: row.next_bump_at,
		reserved: row.reserved === 1,
		target: row.target ?? row.floor,
		until: row.until,
		included: row.included === 1,
		photo: row.photo,
		startPrice: row.start_price,
		startDate: row.start_date,
		cutHearts: row.cut_hearts,
	};
}

/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes ?? (card.bumpAgoDays === null ? null : Math.round(card.bumpAgoDays * 1_440));
	if (minutes === null || !Number.isFinite(minutes)) return prior;
	return new Date(now - minutes * 60_000).toISOString();
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	return laterOf(input.priorNext, estimate);
}

function laterOf(left: string | null, right: string | null): string | null {
	if (left === null) return right;
	if (right === null) return left;
	return Date.parse(left) >= Date.parse(right) ? left : right;
}

/**
 * 판매중 글·규칙·실행 목록. 실행은 승인 없이 `currentBatch`로 만들고,
 * 옛 승인·취소 경로도 남겨 둔다. 폰 파일은 PhoneFiles가 맡는다.
 */
import { DatabaseSync } from "node:sqlite";
import {
	batchSignature,
	DEFAULT_SETTINGS,
	itemsFromProposals,
	type BatchFile,
	type LastRun,
	type ScreenListing,
	type ScreenSettings,
} from "./batch";
import type { SlotStatus } from "./due";
import { nextBumpAt as estimateNextBumpAt } from "./cooldown";
import type { PhoneFiles, PhoneResult } from "./phone";
import { DEFAULT_RULES, proposeBatch, seoulToday, type RuleSet } from "./rules";
import type { DumpCard } from "./dump";
import seed from "./seed.json";
import { uuidv7 } from "./uuid";

export type ListingPatch = {
	title?: string;
	included?: boolean;
	target?: number | null;
	until?: string | null;
	/** 인하 폭의 기준이 되는 시작 가격. null 이면 지금 가격으로 되돌린다. 안 주면 일정이 바뀔 때만 지금 가격으로 다시 잡는다 */
	startPrice?: number | null;
};

/** `saveListing`가 거절한 이유. 저장했으면 null. */
export type SaveListingError = "empty-title" | "duplicate-title";

export type ApproveResult = {
	batch: BatchFile;
	phone: PhoneResult;
	phoneFileExists: boolean;
};

export type CancelResult = {
	status: "cancelled";
	phone: PhoneResult;
	phoneFileExists: boolean;
	notice: string | null;
};

type ListingRow = {
	id: string;
	title: string;
	price: number;
	hearts: number;
	views: number;
	chats: number;
	area: string;
	posted_ago_days: number | null;
	bump_ago_days: number | null;
	bump_count: number | null;
	bumped_at: string | null;
	next_bump_at: string | null;
	reserved: number | null;
	floor: number | null;
	included: number;
	ratio: number | null;
	target: number | null;
	until: string | null;
	photo: string | null;
	start_price: number | null;
	start_date: string | null;
	cut_hearts: number | null;
};

const NOTICE_UNDELIVERED = "취소가 폰에 전달되지 않았어요";

export class MacroStore {
	readonly db: DatabaseSync;
	readonly phone: PhoneFiles;

	constructor(path: string, phone: PhoneFiles) {
		this.db = new DatabaseSync(path);
		this.phone = phone;
		this.db.exec("PRAGMA journal_mode = WAL;");
		this.db.exec("PRAGMA foreign_keys = ON;");
		this.migrate();
		this.ensurePhotoColumn();
		this.ensureScheduleColumns();
		this.ensureBumpColumns();
		this.ensureCutColumn();
		this.moveToEvening();
		this.seedIfEmpty();
		this.fillStartPrices();
	}

	close() {
		this.db.close();
	}

	/** 폰 목록으로 지금 화면을 갈아 끼운다. 문구에 있는 끌올 횟수·시각을 여기서 읽어 둔다. */
	replaceFromPhone(cards: DumpCard[], now: number | Date = Date.now()) {
		const at = now instanceof Date ? now.getTime() : now;
		const previous = new Map(this.listings().map((listing) => [listing.title, listing]));
		this.transact(() => {
			this.db.exec("DELETE FROM listing");
			const insert = this.db.prepare(
				`INSERT INTO listing(id, title, price, hearts, views, chats, area, posted_ago_days, bump_ago_days, bump_count, bumped_at, next_bump_at, reserved, included, target, until, photo, start_price, start_date, cut_hearts)
				 VALUES (:id, :title, :price, :hearts, :views, :chats, :area, :posted_ago_days, :bump_ago_days, :bump_count, :bumped_at, :next_bump_at, :reserved, :included, :target, :until, :photo, :start_price, :start_date, :cut_hearts)`,
			);
			for (const card of cards) {
				const prior = previous.get(card.title);
				const bumpCount = card.bumpCount ?? prior?.bumpCount ?? null;
				const bumpedAt = ingestedBumpedAt(card, prior?.bumpedAt ?? null, at);
				insert.run({
					":id": prior?.id ?? card.title,
					":title": card.title,
					":price": card.price,
					":hearts": card.hearts,
					":views": card.views,
					":chats": card.chats,
					":area": card.area,
					":posted_ago_days": card.postedAgoDays,
					":bump_ago_days": card.bumpAgoDays,
					":bump_count": bumpCount,
					":bumped_at": bumpedAt,
					":next_bump_at": ingestedNextBumpAt({
						priorNext: prior?.nextBumpAt ?? null,
						bumpedAt,
						bumpCount,
					}),
					":reserved": card.reserved ? 1 : 0,
					":included": prior ? (prior.included ? 1 : 0) : 1,
					":target": prior?.target ?? null,
					":until": prior?.until ?? null,
					":photo": card.thumb ?? prior?.photo ?? null,
					":start_price": prior?.startPrice ?? null,
					":start_date": prior?.startDate ?? null,
					// 가격이 전보다 내려갔으면(실행이든 사람이 고쳤든) 그 순간의 관심을 다음 인하의 기준으로 남긴다.
					":cut_hearts": prior && card.price < prior.price ? card.hearts : (prior?.cutHearts ?? null),
				});
			}
		});
		this.markSynced(new Date(at).toISOString());
	}

	/** 화면 데이터를 폰에서 마지막으로 가져온 시각. ISO 문자열. */
	lastSync(): string | null {
		const row = this.db.prepare(`SELECT at FROM sync WHERE id = 1`).get() as { at: string } | undefined;
		return row?.at ?? null;
	}

	markSynced(at: string) {
		this.db
			.prepare(`INSERT INTO sync(id, at) VALUES (1, :at) ON CONFLICT(id) DO UPDATE SET at = excluded.at`)
			.run({ ":at": at });
	}

	/** 폰이 남긴 마지막 실행 로그를 화면 값으로 남긴다. */
	saveRun(run: LastRun) {
		this.db
			.prepare(
				`INSERT INTO last_run(id, at, bumped, priced_only, skipped, note)
				 VALUES (1, :at, :bumped, :priced_only, :skipped, :note)
				 ON CONFLICT(id) DO UPDATE SET at = excluded.at, bumped = excluded.bumped,
				 priced_only = excluded.priced_only, skipped = excluded.skipped, note = excluded.note`,
			)
			.run({
				":at": run.at,
				":bumped": run.bumped,
				":priced_only": run.pricedOnly,
				":skipped": run.skipped,
				":note": run.note,
			});
	}

	listings(): ScreenListing[] {
		const rows = this.db
			.prepare(
				`SELECT id, title, price, hearts, views, chats, area, posted_ago_days, bump_ago_days, bump_count, bumped_at, next_bump_at, reserved, floor, included, ratio, target, until, photo, start_price, start_date, cut_hearts
				 FROM listing ORDER BY rowid`,
			)
			.all() as ListingRow[];
		return rows.map(fromRow);
	}

	/** 제목은 다른 글과 겹치거나 비면 거절한다. 타겟·마감이 바뀌면 지금 가격을 시작 가격으로 새로 잡고, 시작 가격을 직접 주면 그 값을 쓴다. */
	saveListing(id: string, patch: ListingPatch, today = seoulToday()): SaveListingError | null {
		const all = this.listings();
		const current = all.find((listing) => listing.id === id);
		if (!current) return null;
		const title = patch.title === undefined ? current.title : patch.title.trim();
		if (title === "") return "empty-title";
		if (all.some((listing) => listing.id !== id && listing.title === title)) return "duplicate-title";
		const target = patch.target === undefined ? current.target : patch.target;
		const until = patch.until === undefined ? current.until : patch.until;
		const scheduled = target !== null && until !== null;
		const moved = target !== current.target || until !== current.until;
		const explicit = patch.startPrice != null && patch.startPrice > 0 ? Math.round(patch.startPrice) : null;
		const reset = patch.startPrice === null;
		const anchored = scheduled && (moved || reset || current.startPrice == null || current.startDate == null);
		const keptDate = !scheduled ? null : anchored ? today : (current.startDate ?? null);
		this.db
			.prepare(
				`UPDATE listing SET title = :title, included = :included, target = :target, until = :until,
				 start_price = :start_price, start_date = :start_date WHERE id = :id`,
			)
			.run({
				":id": id,
				":title": title,
				":included": (patch.included ?? current.included) ? 1 : 0,
				":target": target,
				":until": until,
				":start_price": !scheduled
					? null
					: explicit !== null
						? explicit
						: anchored
							? current.price
							: (current.startPrice ?? null),
				":start_date": keptDate,
			});
		return null;
	}

	/** 고른 글들의 마감일을 한 번에 바꾼다. 글마다 `saveListing`과 같은 규칙으로 직선을 새로 긋는다. */
	saveUntilMany(ids: string[], until: string, today = seoulToday()) {
		for (const id of ids) this.saveListing(id, { until }, today);
	}

	settings(): ScreenSettings {
		const rows = this.db.prepare(`SELECT key, value FROM setting`).all() as { key: string; value: string }[];
		const map = new Map(rows.map((row) => [row.key, row.value]));
		const number = (key: string, fallback: number) => {
			const raw = map.get(key);
			if (raw === undefined) return fallback;
			const value = Number(raw);
			return Number.isFinite(value) ? value : fallback;
		};
		return {
			dailyLimit: number("dailyLimit", DEFAULT_RULES.dailyLimit),
			minHearts: number("minHearts", DEFAULT_RULES.minHearts),
			heartGrowthPct: number("heartGrowthPct", DEFAULT_RULES.heartGrowthPct),
			runHour: number("runHour", DEFAULT_SETTINGS.runHour),
			runMinute: number("runMinute", DEFAULT_SETTINGS.runMinute),
		};
	}

	saveSettings(settings: ScreenSettings) {
		const upsert = this.db.prepare(
			`INSERT INTO setting(key, value) VALUES (:key, :value)
			ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
		);
		for (const [key, value] of Object.entries(settings)) {
			upsert.run({ ":key": key, ":value": String(value) });
		}
	}

	slot(): { day: string | null; status: SlotStatus | null } {
		const row = this.db.prepare(`SELECT day, status FROM due_slot WHERE id = 1`).get() as
			{ day: string; status: string } | undefined;
		if (!row) return { day: null, status: null };
		if (row.status !== "ran" && row.status !== "skipped" && row.status !== "waiting") {
			return { day: row.day, status: null };
		}
		return { day: row.day, status: row.status };
	}

	saveSlot(day: string, status: SlotStatus) {
		this.db
			.prepare(
				`INSERT INTO due_slot(id, day, status) VALUES (1, :day, :status)
				 ON CONFLICT(id) DO UPDATE SET day = excluded.day, status = excluded.status`,
			)
			.run({ ":day": day, ":status": status });
	}

	lastRun(): LastRun {
		const row = this.db.prepare(`SELECT at, bumped, priced_only, skipped, note FROM last_run WHERE id = 1`).get() as
			{ at: string; bumped: number; priced_only: number; skipped: number; note: string } | undefined;
		if (!row) {
			return { at: "", bumped: 0, pricedOnly: 0, skipped: 0, note: "" };
		}
		return {
			at: row.at,
			bumped: row.bumped,
			pricedOnly: row.priced_only,
			skipped: row.skipped,
			note: row.note,
		};
	}

	activeBatch(): BatchFile | null {
		const gate = this.executionBatch();
		return gate.status === "approved" ? gate.batch : null;
	}

	/** 마지막 배치. 취소는 payload가 아니라 status 열을 따른다. */
	executionBatch(): { status: "none" | "approved" | "cancelled"; batch: BatchFile | null } {
		const row = this.db
			.prepare(`SELECT payload, status FROM batch ORDER BY created_at DESC, rowid DESC LIMIT 1`)
			.get() as { payload: string; status: string } | undefined;
		if (!row) return { status: "none", batch: null };
		const batch = JSON.parse(row.payload) as BatchFile;
		if (row.status === "cancelled") return { status: "cancelled", batch: { ...batch, status: "cancelled" } };
		if (row.status === "approved") return { status: "approved", batch };
		return { status: "none", batch: null };
	}

	signature(): string {
		return batchSignature(this.listings(), this.settings());
	}

	/**
	 * 지금 글과 설정으로 만드는 실행 목록. 저장하지 않는다.
	 * 실행은 승인 없이 이 값을 그대로 쓴다.
	 */
	currentBatch(now: number | Date = Date.now()): BatchFile {
		const at = now instanceof Date ? now.getTime() : now;
		const listings = this.listings();
		const settings = this.settings();
		const rules: RuleSet = {
			dailyLimit: settings.dailyLimit,
			minHearts: settings.minHearts,
			heartGrowthPct: settings.heartGrowthPct,
		};
		const proposals = proposeBatch(listings, rules, seoulToday(at), at);
		return {
			id: uuidv7(),
			status: "approved",
			signature: batchSignature(listings, settings),
			runHour: settings.runHour,
			runMinute: settings.runMinute,
			items: itemsFromProposals(listings, proposals),
			approvedAt: new Date(at).toISOString(),
		};
	}

	/** 지금까지 끌어올린 횟수. 모르면 0. */
	previousBumpCount(listingId: string): number {
		const row = this.db.prepare(`SELECT bump_count FROM listing WHERE id = :id`).get({ ":id": listingId }) as
			{ bump_count: number | null } | undefined;
		return row?.bump_count ?? 0;
	}

	/** 실행이 끌올 하나를 마쳤을 때. 횟수를 안 주면 지금 값 + 1, 다음 시각을 안 주면 추정표를 쓴다. */
	recordBump(
		listingId: string,
		bump: { bumpedAt: string; bumpCount?: number | null; nextBumpAt?: string | null },
	): void {
		const row = this.listings().find((listing) => listing.id === listingId);
		if (!row) return;
		const bumpCount = bump.bumpCount ?? (row.bumpCount ?? 0) + 1;
		const next = bump.nextBumpAt ?? estimateNextBumpAt(bump.bumpedAt, bumpCount);
		this.db
			.prepare(
				`UPDATE listing SET bumped_at = :bumped_at, bump_count = :bump_count, next_bump_at = :next_bump_at
				 WHERE id = :id`,
			)
			.run({
				":id": listingId,
				":bumped_at": bump.bumpedAt,
				":bump_count": bumpCount,
				":next_bump_at": next,
			});
	}

	/** 폰에 뜬 남은 시간을 그대로 남긴다. 관측값은 추정을 이긴다. */
	recordCooldown(listingId: string, next: string): void {
		this.db.prepare(`UPDATE listing SET next_bump_at = :next WHERE id = :id`).run({
			":id": listingId,
			":next": next,
		});
	}

	recordReserved(listingId: string): void {
		this.db.prepare(`UPDATE listing SET reserved = 1 WHERE id = :id`).run({ ":id": listingId });
	}

	approve(): ApproveResult {
		const batch = this.currentBatch();
		this.db
			.prepare(
				`INSERT INTO batch(id, status, signature, payload, phone_ok, phone_error, created_at)
				 VALUES (:id, :status, :signature, :payload, :phone_ok, :phone_error, :created_at)`,
			)
			.run({
				":id": batch.id,
				":status": "approved",
				":signature": batch.signature,
				":payload": JSON.stringify(batch),
				":phone_ok": 1,
				":phone_error": null,
				":created_at": batch.approvedAt,
			});
		return { batch, phone: { ok: true }, phoneFileExists: false };
	}

	cancel(): CancelResult {
		const active = this.activeBatch();
		if (!active) {
			return { status: "cancelled", phone: { ok: true }, phoneFileExists: false, notice: null };
		}
		const hadFile = this.phone.exists();
		const phone = this.phone.remove();
		this.db.prepare(`UPDATE batch SET status = 'cancelled' WHERE id = :id`).run({ ":id": active.id });
		const leftover = !phone.ok && hadFile;
		return {
			status: "cancelled",
			phone: leftover ? phone : { ok: true },
			phoneFileExists: leftover,
			notice: leftover ? NOTICE_UNDELIVERED : null,
		};
	}

	private migrate() {
		this.db.exec(`
			CREATE TABLE IF NOT EXISTS listing (
				id TEXT PRIMARY KEY,
				title TEXT NOT NULL,
				price INTEGER NOT NULL,
				hearts INTEGER NOT NULL,
				views INTEGER NOT NULL,
				chats INTEGER NOT NULL,
				area TEXT NOT NULL,
				posted_ago_days INTEGER,
				bump_ago_days INTEGER,
				bump_count INTEGER,
				bumped_at TEXT,
				next_bump_at TEXT,
				reserved INTEGER NOT NULL DEFAULT 0,
				floor INTEGER,
				included INTEGER NOT NULL,
				ratio INTEGER,
				target INTEGER,
				until TEXT,
				photo TEXT,
				start_price INTEGER,
				start_date TEXT,
				cut_hearts INTEGER
			);
			CREATE TABLE IF NOT EXISTS setting (
				key TEXT PRIMARY KEY,
				value TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS batch (
				id TEXT PRIMARY KEY,
				status TEXT NOT NULL,
				signature TEXT NOT NULL,
				payload TEXT NOT NULL,
				phone_ok INTEGER NOT NULL,
				phone_error TEXT,
				created_at TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS last_run (
				id INTEGER PRIMARY KEY CHECK (id = 1),
				at TEXT NOT NULL,
				bumped INTEGER NOT NULL,
				priced_only INTEGER NOT NULL,
				skipped INTEGER NOT NULL,
				note TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS sync (
				id INTEGER PRIMARY KEY CHECK (id = 1),
				at TEXT NOT NULL
			);
			CREATE TABLE IF NOT EXISTS due_slot (
				id INTEGER PRIMARY KEY CHECK (id = 1),
				day TEXT NOT NULL,
				status TEXT NOT NULL
			);
		`);
	}

	private seedIfEmpty() {
		const count = (this.db.prepare(`SELECT COUNT(*) AS n FROM listing`).get() as { n: number } | undefined)?.n ?? 0;
		if (count > 0) return;
		const insert = this.db.prepare(
			`INSERT INTO listing(id, title, price, hearts, views, chats, area, posted_ago_days, bump_ago_days, bump_count, bumped_at, next_bump_at, included, target, until, photo)
			 VALUES (:id, :title, :price, :hearts, :views, :chats, :area, :posted_ago_days, :bump_ago_days, :bump_count, :bumped_at, :next_bump_at, :included, :target, :until, :photo)`,
		);
		// 시드는 지금 시각에서 `끌올 N일 전`을 되짚어 쓰고, 다음 시각은 추정표로 채운다.
		const now = Date.now();
		this.transact(() => {
			for (const post of seed.posts) {
				const bumpedAt = post.bumpAgoDays === null ? null : new Date(now - post.bumpAgoDays * 86_400_000).toISOString();
				insert.run({
					":id": post.id,
					":title": post.title,
					":price": post.price,
					":hearts": post.hearts,
					":views": post.views,
					":chats": post.chats,
					":area": post.area,
					":posted_ago_days": post.postedAgoDays,
					":bump_ago_days": post.bumpAgoDays,
					":bump_count": post.bumpCount ?? null,
					":bumped_at": bumpedAt,
					":next_bump_at": bumpedAt === null || !post.bumpCount ? null : estimateNextBumpAt(bumpedAt, post.bumpCount),
					":included": post.included ? 1 : 0,
					":target": post.target,
					":until": post.until,
					":photo": null,
				});
			}
			const upsert = this.db.prepare(
				`INSERT INTO setting(key, value) VALUES (:key, :value) ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
			);
			for (const [key, value] of Object.entries(DEFAULT_SETTINGS)) {
				upsert.run({ ":key": key, ":value": String(value) });
			}
			this.db
				.prepare(
					`INSERT INTO last_run(id, at, bumped, priced_only, skipped, note)
					 VALUES (1, :at, :bumped, :priced_only, :skipped, :note)`,
				)
				.run({
					":at": seed.lastRun.at,
					":bumped": seed.lastRun.bumped,
					":priced_only": seed.lastRun.pricedOnly,
					":skipped": seed.lastRun.skipped,
					":note": seed.lastRun.note,
				});
		});
	}

	private ensurePhotoColumn() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		if (cols.some((col) => col.name === "photo")) return;
		this.db.exec("ALTER TABLE listing ADD COLUMN photo TEXT");
	}

	/** 끌올 횟수·마지막 시각·다음 가능 시각. 옛 DB는 칸을 더한다. */
	ensureBumpColumns() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		const names = new Set(cols.map((col) => col.name));
		if (!names.has("bump_count")) this.db.exec("ALTER TABLE listing ADD COLUMN bump_count INTEGER");
		if (!names.has("bumped_at")) this.db.exec("ALTER TABLE listing ADD COLUMN bumped_at TEXT");
		if (!names.has("next_bump_at")) this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_at TEXT");
		if (!names.has("reserved")) this.db.exec("ALTER TABLE listing ADD COLUMN reserved INTEGER NOT NULL DEFAULT 0");
		// 칸이 생기기 전에 읽은 글은 '끌올 N일 전' 으로 마지막 끌올을 어림한다. 다음 새로 읽기가 덮는다.
		this.db.exec(
			`UPDATE listing SET bumped_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-' || bump_ago_days || ' days')
			 WHERE bumped_at IS NULL AND bump_ago_days IS NOT NULL`,
		);
	}

	/** 마지막 인하 때의 관심 수. 옛 DB는 칸을 더한다. */
	private ensureCutColumn() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		if (cols.some((col) => col.name === "cut_hearts")) return;
		this.db.exec("ALTER TABLE listing ADD COLUMN cut_hearts INTEGER");
	}

	/** 예전 기본값(아침 8시 5분)으로 저장된 회차는 저녁 19:00으로 옮긴다. */
	private moveToEvening() {
		this.db
			.prepare(`UPDATE setting SET value = :hour WHERE key = 'runHour' AND value = '8'`)
			.run({ ":hour": String(DEFAULT_SETTINGS.runHour) });
		this.db
			.prepare(`UPDATE setting SET value = :minute WHERE key = 'runMinute' AND value = '5'`)
			.run({ ":minute": String(DEFAULT_SETTINGS.runMinute) });
	}

	ensureScheduleColumns() {
		const cols = this.db.prepare(`PRAGMA table_info(listing)`).all() as { name: string }[];
		const names = new Set(cols.map((col) => col.name));
		if (!names.has("target")) {
			this.db.exec("ALTER TABLE listing ADD COLUMN target INTEGER");
			this.db.exec("UPDATE listing SET target = floor WHERE floor IS NOT NULL");
		}
		if (!names.has("until")) this.db.exec("ALTER TABLE listing ADD COLUMN until TEXT");
		if (!names.has("start_price")) this.db.exec("ALTER TABLE listing ADD COLUMN start_price INTEGER");
		if (!names.has("start_date")) this.db.exec("ALTER TABLE listing ADD COLUMN start_date TEXT");
		this.fillStartPrices();
	}

	/** 시작가가 없던 일정은 처음 열린 날의 가격에서 직선을 시작한다. */
	private fillStartPrices() {
		this.db
			.prepare(
				`UPDATE listing SET start_price = price, start_date = :today
				 WHERE target IS NOT NULL AND until IS NOT NULL AND start_price IS NULL`,
			)
			.run({ ":today": seoulToday() });
	}

	private transact(fn: () => void) {
		this.db.exec("BEGIN");
		try {
			fn();
			this.db.exec("COMMIT");
		} catch (error) {
			this.db.exec("ROLLBACK");
			throw error;
		}
	}
}

function fromRow(row: ListingRow): ScreenListing {
	return {
		id: row.id,
		title: row.title,
		price: row.price,
		hearts: row.hearts,
		views: row.views,
		chats: row.chats,
		area: row.area,
		postedAgoDays: row.posted_ago_days,
		bumpAgoDays: row.bump_ago_days,
		bumpCount: row.bump_count,
		bumpedAt: row.bumped_at,
		nextBumpAt: row.next_bump_at,
		reserved: row.reserved === 1,
		target: row.target ?? row.floor,
		until: row.until,
		included: row.included === 1,
		photo: row.photo,
		startPrice: row.start_price,
		startDate: row.start_date,
		cutHearts: row.cut_hearts,
	};
}

/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes ?? (card.bumpAgoDays === null ? null : Math.round(card.bumpAgoDays * 1_440));
	if (minutes === null || !Number.isFinite(minutes)) return prior;
	return new Date(now - minutes * 60_000).toISOString();
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	return laterOf(input.priorNext, estimate);
}

function laterOf(left: string | null, right: string | null): string | null {
	if (left === null) return right;
	if (right === null) return left;
	return Date.parse(left) >= Date.parse(right) ? left : right;
}

/**
 * PC adb로 판매관리를 정해진 순서만 조작한다. PIN은 넣지 않는다.
 * 드라이런은 끌어올리기 창의 가격 칸만 읽고 확정·수정 완료를 누르지 않는다.
 */
