describe("옛 DB", () => {
	test("target·until 칸이 없으면 만들고 저장이 남는다", () => {
		const dir = mkdtempSync(join(tmpdir(), "macro-"));
		const path = join(dir, "old.sqlite");
		const raw = new DatabaseSync(path);
		raw.exec(`CREATE TABLE listing (
			id TEXT PRIMARY KEY, title TEXT NOT NULL, price INTEGER NOT NULL, hearts INTEGER NOT NULL,
			views INTEGER NOT NULL, chats INTEGER NOT NULL, area TEXT NOT NULL,
			posted_ago_days INTEGER, bump_ago_days INTEGER, floor INTEGER, included INTEGER NOT NULL, ratio INTEGER, photo TEXT
		)`);
		raw
			.prepare(
				`INSERT INTO listing(id, title, price, hearts, views, chats, area, included, floor)
				 VALUES ('ac', '에어컨', 300000, 1, 0, 0, '방배4동', 1, 280000)`,
			)
			.run();
		raw.close();
		const store = new MacroStore(path, memoryPhone());
		stores.push(store);
		expect(store.listings()[0]?.target).toBe(280_000);
		expect(store.listings()[0]).toMatchObject({ bumpCount: null, bumpedAt: null, nextBumpAt: null, cutHearts: null });
		store.recordBump("ac", { bumpedAt: "2026-10-28T10:00:00.000Z" });
		expect(store.listings()[0]).toMatchObject({
			bumpCount: 1,
			bumpedAt: "2026-10-28T10:00:00.000Z",
			nextBumpAt: "2026-10-30T22:00:00.000Z",
		});
		store.saveListing("ac", { target: 250_000, until: "2026-11-30" });
		expect(store.listings()[0]).toMatchObject({ target: 250_000, until: "2026-11-30" });
		store.close();
		stores.pop();
		rmSync(dir, { recursive: true, force: true });
	});
});

describe("폰 로그 회수", () => {
	test("폰이 남긴 마지막 실행을 화면 값으로 옮기고 동기화 시각을 남긴다", () => {
		const { store } = open();
		expect(store.lastSync()).toBeNull();
		store.saveRun({ at: "2026-10-27T05:37:30.861Z", bumped: 5, pricedOnly: 18, skipped: 2, note: "" });
		expect(store.lastRun()).toEqual({
			at: "2026-10-27T05:37:30.861Z",
			bumped: 5,
			pricedOnly: 18,
			skipped: 2,
			note: "",
		});
		store.replaceFromPhone([]);
		expect(store.lastSync()).toMatch(/^\d{4}-\d{2}-\d{2}T/);
	});

	test("깨진 폰 로그는 화면 값을 바꾸지 않는다", () => {
		const { store } = open();
		expect(lastRunFromLog("{not json")).toBeNull();
		expect(lastRunFromLog("[]")).toBeNull();
		expect(lastRunFromLog('{"at":"x","bumped":"3","pricedOnly":null}')).toEqual({
			at: "x",
			bumped: 3,
			pricedOnly: 0,
			skipped: 0,
			note: "",
		});
		expect(store.lastRun().at).toBe("10월 27일 오후 7:00");
	});
});

