edits.oldText:
scrollToEdge(serial, exec, ops, "bottom");
let prev = "";
let stuck = 0;
let page = 0;

edits.newText:
scrollToEdge(serial, exec, ops, "bottom");
let prev = "";
let stuck = 0;
let page = 0;
// 창을 닫고 나면 목록이 맨 위로 되돌아간다. 위로 한 칸씩 헛걷지 말고 바로 맨 아래로 간다.
let atTopAfterClose = false;

edits.oldText:
let reread = false;
const xml = settledXml(serial, exec);
const nodes = parseNodes(xml);
const parsed = parseSalesDump(xml);

edits.newText:
let reread = false;
const xml = settledXml(serial, exec);
const nodes = parseNodes(xml);
const parsed = parseSalesDump(xml);
if (!parsed.ok && parsed.error.kind === "not-sales-screen") {
	// 판매관리가 아닌 화면(홈 등)에서 스와이프하면 앱을 벗어난다. 딥링크로 다시 연다.
	openSales(serial, exec);
	atTopAfterClose = true;
	continue;
}

edits.oldText:
// 카드가 화면에서 사라졌다. 목록이 움직였으니 글은 남겨 두고, 다시 읽어 찾는다.
if (done === "gone") {
	reread = true;
	break;
}

edits.newText:
// 카드가 화면에서 사라졌다. 목록이 움직였으니 글은 남겨 두고, 다시 읽어 찾는다.
if (done === "gone") {
	reread = true;
	if (atTopAfterClose) break;
	// 낡은 덤프의 카드가 지금 화면에 없으면 목록이 맨 위로 되돌아간 것이다.
	atTopAfterClose = true;
	break;
}

edits.oldText:
// 끌어올린 글은 목록 맨 위로 옮겨 가 화면 배치가 바뀐다. 이 덤프의 나머지 카드는 믿지 않고 다시 읽는다.
if (done === "bump") {
	reread = true;
	break;
}

edits.newText:
// 창을 닫고 돌아오면 목록이 맨 위로 되돌아간다(끌어올리기 성공뿐 아니라 쿨타임 안내·가격 수정도).
// 이 덤프의 나머지 카드는 믿지 않고, 다음 이동은 맨 아래로 바로 간다.
atTopAfterClose = true;
if (done === "bump") {
	reread = true;
	break;
}

if (pending.size === 0) break;
if (atTopAfterClose) {
	atTopAfterClose = false;
	reread = false;
	prev = "";
	stuck = 0;
	swipeList(serial, exec, ops, "창을 닫고 맨 위로 되돌아가서 맨 아래로 바로", "bottom");
	page += 1;
	continue;
}
if (reread) continue;

