				`UPDATE listing SET title = :title, included = :included, target = :target, until = :until,
				 start_price = :start_price, start_date = :start_date WHERE id = :id`,
			)
			.run({
				":id": id,
				":title": title,
				":included": (patch.included ?? current.included) ? 1 : 0,
				":target": target,
				":until": until,
				":start_price": !scheduled
					? null
					: explicit !== null
						? explicit
						: anchored
							? current.price
							: (current.startPrice ?? null),
				":start_date": keptDate,
			});
		return null;
	}

	/** 고른 글들의 마감일을 한 번에 바꾼다. 글마다 `saveListing`과 같은 규칙으로 직선을 새로 긋는다. */
	saveUntilMany(ids: string[], until: string, today = seoulToday()) {
		for (const id of ids) this.saveListing(id, { until }, today);
	}

	settings(): ScreenSettings {
		const rows = this.db.prepare(`SELECT key, value FROM setting`).all() as { key: string; value: string }[];
		const map = new Map(rows.map((row) => [row.key, row.value]));
		const number = (key: string, fallback: number) => {
			const raw = map.get(key);
			if (raw === undefined) return fallback;
			const value = Number(raw);
			return Number.isFinite(value) ? value : fallback;
		};
		return {
			dailyLimit: number("dailyLimit", DEFAULT_RULES.dailyLimit),
			minHearts: number("minHearts", DEFAULT_RULES.minHearts),
			heartGrowthPct: number("heartGrowthPct", DEFAULT_RULES.heartGrowthPct),
			runHour: number("runHour", DEFAULT_SETTINGS.runHour),
			runMinute: number("runMinute", DEFAULT_SETTINGS.runMinute),
		};
	}

	saveSettings(settings: ScreenSettings) {
		const upsert = this.db.prepare(
			`INSERT INTO setting(key, value) VALUES (:key, :value)
			ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
		);
		for (const [key, value] of Object.entries(settings)) {
			upsert.run({ ":key": key, ":value": String(value) });
		}
	}

	slot(): { day: string | null; status: SlotStatus | null } {
		const row = this.db.prepare(`SELECT day, status FROM due_slot WHERE id = 1`).get() as
			{ day: string; status: string } | undefined;
		if (!row) return { day: null, status: null };
		if (row.status !== "ran" && row.status !== "skipped" && row.status !== "waiting") {
			return { day: row.day, status: null };
		}
		return { day: row.day, status: row.status };
	}

	saveSlot(day: string, status: SlotStatus) {
		this.db
			.prepare(
				`INSERT INTO due_slot(id, day, status) VALUES (1, :day, :status)
				 ON CONFLICT(id) DO UPDATE SET day = excluded.day, status = excluded.status`,
			)
			.run({ ":day": day, ":status": status });
	}

	lastRun(): LastRun {
		const row = this.db.prepare(`SELECT at, bumped, priced_only, skipped, note FROM last_run WHERE id = 1`).get() as
			{ at: string; bumped: number; priced_only: number; skipped: number; note: string } | undefined;
		if (!row) {
			return { at: "", bumped: 0, pricedOnly: 0, skipped: 0, note: "" };
		}
		return {
			at: row.at,
			bumped: row.bumped,
			pricedOnly: row.priced_only,
			skipped: row.skipped,
			note: row.note,
		};
	}

	activeBatch(): BatchFile | null {
		const gate = this.executionBatch();
		return gate.status === "approved" ? gate.batch : null;
	}

	/** 마지막 배치. 취소는 payload가 아니라 status 열을 따른다. */
	executionBatch(): { status: "none" | "approved" | "cancelled"; batch: BatchFile | null } {
		const row = this.db
			.prepare(`SELECT payload, status FROM batch ORDER BY created_at DESC, rowid DESC LIMIT 1`)
			.get() as { payload: string; status: string } | undefined;
		if (!row) return { status: "none", batch: null };
		const batch = JSON.parse(row.payload) as BatchFile;
		if (row.status === "cancelled") return { status: "cancelled", batch: { ...batch, status: "cancelled" } };
		if (row.status === "approved") return { status: "approved", batch };
		return { status: "none", batch: null };
	}

	signature(): string {
		return batchSignature(this.listings(), this.settings());
	}

	/**
	 * 지금 글과 설정으로 만드는 실행 목록. 저장하지 않는다.
	 * 실행은 승인 없이 이 값을 그대로 쓴다.
	 */
	currentBatch(now: number | Date = Date.now()): BatchFile {
		const at = now instanceof Date ? now.getTime() : now;
		const listings = this.listings();
		const settings = this.settings();
		const rules: RuleSet = {
			dailyLimit: settings.dailyLimit,
			minHearts: settings.minHearts,
			heartGrowthPct: settings.heartGrowthPct,
		};
		const proposals = proposeBatch(listings, rules, seoulToday(at), at);
		return {
			id: uuidv7(),
			status: "approved",
			signature: batchSignature(listings, settings),
			runHour: settings.runHour,
			runMinute: settings.runMinute,
			items: itemsFromProposals(listings, proposals),
			approvedAt: new Date(at).toISOString(),
		};
	}

	/** 지금까지 끌어올린 횟수. 모르면 0. */
	previousBumpCount(listingId: string): number {
		const row = this.db.prepare(`SELECT bump_count FROM listing WHERE id = :id`).get({ ":id": listingId }) as
			{ bump_count: number | null } | undefined;
		return row?.bump_count ?? 0;
	}

	/** 실행이 끌올 하나를 마쳤을 때. 횟수를 안 주면 지금 값 + 1, 다음 시각을 안 주면 추정표를 쓴다. */
	recordBump(
		listingId: string,
		bump: { bumpedAt: string; bumpCount?: number | null; nextBumpAt?: string | null },
	): void {
		const row = this.listings().find((listing) => listing.id === listingId);
		if (!row) return;
		const bumpCount = bump.bumpCount ?? (row.bumpCount ?? 0) + 1;
		const next = bump.nextBumpAt ?? estimateNextBumpAt(bump.bumpedAt, bumpCount);
		this.db
			.prepare(
				`UPDATE listing SET bumped_at = :bumped_at, bump_count = :bump_count, next_bump_at = :next_bump_at
				 WHERE id = :id`,
			)
			.run({
				":id": listingId,
				":bumped_at": bump.bumpedAt,
				":bump_count": bumpCount,
				":next_bump_at": next,
			});
	}

	/** 폰에 뜬 남은 시간을 그대로 남긴다. 관측값은 추정을 이긴다. */
	recordCooldown(listingId: string, next: string): void {
		this.db.prepare(`UPDATE listing SET next_bump_at = :next WHERE id = :id`).run({
			":id": listingId,
			":next": next,
		});
	}

	recordReserved(listingId: string): void {
		this.db.prepare(`UPDATE listing SET reserved = 1 WHERE id = :id`).run({ ":id": listingId });
	}

	approve(): ApproveResult {
		const batch = this.currentBatch();
		this.db
			.prepare(
				`INSERT INTO batch(id, status, signature, payload, phone_ok, phone_error, created_at)
				 VALUES (:id, :status, :signature, :payload, :phone_ok, :phone_error, :created_at)`,
			)
			.run({
				":id": batch.id,
				":status": "approved",
				":signature": batch.signature,
				":payload": JSON.stringify(batch),
				":phone_ok": 1,
				":phone_error": null,
				":created_at": batch.approvedAt,
			});
		return { batch, phone: { ok: true }, phoneFileExists: false };
	}

	cancel(): CancelResult {
		const active = this.activeBatch();
		if (!active) {
			return { status: "cancelled", phone: { ok: true }, phoneFileExists: false, notice: null };
		}
		const hadFile = this.phone.exists();
		const phone = this.phone.remove();
		this.db.prepare(`UPDATE batch SET status = 'cancelled' WHERE id = :id`).run({ ":id": active.id });
		const leftover = !phone.ok && hadFile;
		return {
			status: "cancelled",
			phone: leftover ? phone : { ok: true },
			phoneFileExists: leftover,
			notice: leftover ? NOTICE_UNDELIVERED : null,
		};
	}

	private migrate() {
