/**
 * 끌어올리기 창을 열고 가격 칸을 읽는다. 확정은 dry가 아닐 때만, 그리고 칸 값이 승인값과 같을 때만.
 * 홍보하기·추천받기·삭제·숨기기·거래완료·예약중·변경하기는 누르지 않는다.
 */
import { FORBIDDEN_LABELS } from "./run-plan";

export type Point = { x: number; y: number; text: string; desc: string };

export type ScreenNode = Point & { cls: string; w: number; h: number; checkable?: boolean; checked?: boolean };

export type ScreenOp =
	{ kind: "tap"; x: number; y: number; label: string } | { kind: "back" } | { kind: "type"; text: string };

export type BumpRead = {
	title: string;
	price: number;
	confirmed: false;
};

const FORBIDDEN = new Set<string>(FORBIDDEN_LABELS);

export function parseNodes(xml: string): ScreenNode[] {
	return [...xml.matchAll(/<node\b([^>]*)\/?>/g)].map((match) => attrs(match[1]));
}

export function center(node: { x: number; y: number; w: number; h: number }): { x: number; y: number } {
	return { x: Math.floor(node.x + node.w / 2), y: Math.floor(node.y + node.h / 2) };
}

export function forbiddenLabel(text: string, desc: string): boolean {
	return FORBIDDEN.has(text) || FORBIDDEN.has(desc);
}

export function priceField(nodes: ScreenNode[]): ScreenNode | null {
	const numeric = nodes.filter(
		(node) => /^[\d,]+$/.test(node.text) && node.text.length >= 2 && node.w > 40 && node.h > 20,
	);
	if (numeric.length === 0) return null;
	return numeric.sort((a, b) => a.y - b.y)[0] ?? null;
}

/** 게시글 수정의 가격 칸. `￦ 8,000`처럼 통화 기호가 붙어도 찾는다. */
export function editPriceField(nodes: ScreenNode[]): ScreenNode | null {
	const marked = nodes.filter((node) => {
		const text = node.text.replace(/\s/g, "");
		return node.w > 180 && node.h > 30 && /^[₩￦][\d,]+$/.test(text);
	});
	return marked.sort((a, b) => a.y - b.y)[0] ?? null;
}

/**
 * 수정 창에서 가격 칸을 눌러도 되는 상태. 설명이 긴 글은 칸이 하단 `수정 완료` 바에 반쯤 가린 채 덤프에 잡힌다.
 * 그 가운데를 누르면 바나 빈 곳이 눌려 가격이 안 바뀐다(2026-11-06 LG 트롬 건조기). 칸 아래끝이 바 위로 올라올 때까지 더 민다.
 */
export function editPriceReady(nodes: ScreenNode[], confirmLabel = "수정 완료"): ScreenNode | null {
	const field = editPriceField(nodes);
	if (!field) return null;
	const bar = nodes.find((node) => node.text === confirmLabel || node.desc === confirmLabel);
	if (bar && field.y + field.h > bar.y - 8) return null;
	return field;
}

export function parseWon(text: string): number {
	const digits = text.replace(/[^\d]/g, "");
	return digits === "" ? 0 : Number(digits);
}

export function onBumpSheet(xml: string): boolean {
	return (xml.includes("가격을 낮추면") || xml.includes("판매 확률")) && priceField(parseNodes(xml)) !== null;
}

/** 카드의 끌어올리기. 확정 버튼(맨 아래 text)과 구분한다. */
export function cardBump(nodes: ScreenNode[], title: string): ScreenNode | null {
	const titleNode = nodes.find((node) => node.text === title);
	if (!titleNode) return null;
	const bumps = nodes.filter((node) => node.desc === "끌어올리기" && !forbiddenLabel(node.text, node.desc));
	const below = bumps.filter((node) => node.y >= titleNode.y - 40 && node.y < titleNode.y + 420);
	return below.sort((a, b) => a.y - b.y)[0] ?? null;
}

export function confirmBump(nodes: ScreenNode[]): ScreenNode | null {
	const hits = nodes.filter((node) => node.text === "끌어올리기" && !forbiddenLabel(node.text, node.desc));
	if (hits.length === 0) return null;
	return hits.sort((a, b) => b.y - a.y)[0] ?? null;
}

/** 숫자 키보드가 확정 버튼을 덮고 있으면 그 좌표를 누르면 안 된다. */
export function keyboardOpen(xml: string): boolean {
	return xml.includes('text="0"') && xml.includes('text="1"') && xml.includes('text="완료"');
}

export function imeDone(nodes: ScreenNode[]): ScreenNode | null {
	return nodes.find((node) => node.text === "완료") ?? null;
}

export type DryPlan = { ok: true; tap: { x: number; y: number }; price: number } | { ok: false; message: string };

/** 창이 열린 덤프에서 가격만 읽는다. 확정 좌표는 만들지 않는다. */
export function planDryRead(xml: string, title: string): DryPlan {
	if (!onBumpSheet(xml)) return { ok: false, message: "끌어올리기 창이 아니에요" };
	const field = priceField(parseNodes(xml));
	if (!field) return { ok: false, message: "가격 칸이 없어요" };
	if (xml.includes(title) === false && title !== "") {
		return { ok: false, message: "연 글의 제목이 덤프에 없어요" };
	}
	return { ok: true, tap: center(field), price: parseWon(field.text) };
}

export function assertNoConfirm(ops: ScreenOp[]): boolean {
	return ops.every((op) => op.kind !== "tap" || (op.label !== "끌어올리기" && op.label !== "수정 완료"));
}

function attrs(raw: string): ScreenNode {
	const get = (name: string) => raw.match(new RegExp(`${name}="([^"]*)"`))?.[1] ?? "";
	const box = get("bounds").match(/\[(\d+),(\d+)\]\[(\d+),(\d+)\]/);
	const x = box ? Number(box[1]) : 0;
	const y = box ? Number(box[2]) : 0;
	const x2 = box ? Number(box[3]) : 0;
	const y2 = box ? Number(box[4]) : 0;
	return {
		text: get("text"),
		desc: get("content-desc"),
		cls: get("class"),
		x,
		y,
		w: x2 - x,
		h: y2 - y,
		checkable: get("checkable") === "true",
		checked: get("checked") === "true",
	};
}

/**
 * 화면 트리 읽기. `uiautomator dump` 는 화면이 잠잠해질 때까지 기다려 한 번에 2초쯤 걸린다
 * (261105 회차: 덤프 208번이 652초 중 490초).
 * 폰 쪽 일은 droid 가 한다: `droid dump` 는 상주 NodeDump 서버(app_process, 앱 설치 없음)에 파일로 요청해
 * 덤프 한 번을 adb 왕복 하나로 끝내고, 서버가 안 되는 폰이면 uiautomator 로 돌아간다.
 * `NODE_DUMP=off` 는 droid 가 직접 읽어 uiautomator 만 쓴다(dev/droid/nodes.go).
 * droid 가 없는 경로(테스트의 adb 가짜)는 uiautomator 로만 읽는다.
 */
import { spawnSync } from "node:child_process";
import { droidOf } from "./droid";
import type { AdbExec } from "./phone";

const DUMP_FILE = "/sdcard/window_dump.xml";

/** droid 없이 도는 경로에서 상주 서버를 내리는 셸. droid 는 `rest --nodes` 가 같은 일을 한다. */
export const STOP_SCRIPT =
	"[ -f /data/local/tmp/droid-nodes/pid ] && kill $(cat /data/local/tmp/droid-nodes/pid) 2>/dev/null; rm -rf /data/local/tmp/droid-nodes";

/** 지금 화면의 XML. 빈 문자열이면 못 읽은 것이다(전환 중인 화면이거나 기기 문제). */
export function dumpScreen(serial: string, exec: AdbExec): string {
	const d = droidOf(exec);
	// exit 2 는 이번 한 번 화면이 비었다는 뜻이고 3 은 기기 문제다. 둘 다 이번 덤프만 빈 문자열이다.
	if (d) {
		const run = d(["dump", "--serial", serial]);
		return run.status === 0 ? run.stdout.trim() : "";
	}
	exec(["-s", serial, "shell", "uiautomator", "dump", DUMP_FILE]);
	return exec(["-s", serial, "shell", "cat", DUMP_FILE]).stdout;
}

/** 회차 끝에 서버를 내린다. 안 내려도 요청이 없으면 스스로 끝난다. */
export function stopNodeServer(serial: string, exec: AdbExec) {
	const d = droidOf(exec);
	if (d) {
		d(["rest", "--nodes", "--serial", serial]);
		return;
	}
	exec(["-s", serial, "shell", STOP_SCRIPT]);
}

/**
 * 스와이프 뒤 목록이 멈출 때까지 읽는다. NodeDump 는 0.2초면 읽어서, 관성으로 아직 움직이는 목록을 잡으면
 * 앞 창과 같은 창으로 보고 '더 안 내려감'으로 끝낸다(261105 21:02: 판매중 32건 중 18·21건).
 * uiautomator 는 잠잠해질 때까지 기다려서 이 문제가 없었다. 연속 두 덤프가 같으면 멈춘 것이다.
 */
export function settledDump(read: () => string, pause: (ms: number) => void = (ms) => void spawnSync("sleep", [(ms / 1000).toFixed(3)]), tries = 6): string {
	let prev = read();
	for (let i = 0; i < tries; i++) {
		pause(150);
		const next = read();
		if (next === prev) return next;
		prev = next;
	}
	return prev;
}

/**
 * 판매관리 uiautomator 덤프 → 판매중 카드.
 * 숫자만 있고 아이콘 desc는 없다. 개수로만 조회·채팅·하트를 나눈다(계획 §4).
 * 숫자가 2개면 조회+하트인지 조회+채팅인지 단정하지 않고 멈춘다.
 */

export type PhotoBox = { x: number; y: number; w: number; h: number };

export type DumpCard = {
	title: string;
	price: number;
	area: string;
	postedAgoDays: number | null;
	bumpAgoDays: number | null;
	/** `끌올 N시간 전`까지 분으로 남긴 값. 끌올 문구가 없으면 null */
	bumpAgoMinutes: number | null;
	bumpCount: number | null;
	/** 판매중 탭에 같이 있는 예약중 글. 거래 약속이 잡혀 있어 매크로가 건드리지 않는다. */
	reserved?: boolean;
	views: number;
	chats: number;
	hearts: number;
	photo?: PhotoBox | null;
	thumb?: string | null;
};

export type DumpError = {
	kind: "ambiguous-stats" | "no-sales" | "not-sales-screen";
	message: string;
	title?: string;
};

export type DumpResult = { ok: true; cards: DumpCard[]; tabCount: number | null } | { ok: false; error: DumpError };

type Node = {
	text: string;
	desc: string;
	cls: string;
	x: number;
	y: number;
	w: number;
	h: number;
};

const PRICE = /^[\d,]+원$/;
const STAT = /^\d+$/;
const CAPTION = /·/;
/** 판매중 탭의 카드는 이 상태 글자로 시작한다. */
const STATUS = new Set(["판매중", "예약중"]);

function isStatus(node: Node): boolean {
	return STATUS.has(node.text) && node.desc === "";
}

export function parseSalesDump(xml: string): DumpResult {
	if (!xml.includes("판매관리") && !xml.includes("판매중")) {
		return { ok: false, error: { kind: "not-sales-screen", message: "판매관리 화면이 아니에요" } };
	}
	const nodes = [...xml.matchAll(/<node\b([^>]*)>/g)].map((match) => attrs(match[1]));
	const tab = nodes.find((node) => node.desc.startsWith("판매중 "));
	const tabCount = tab ? Number(tab.desc.replace(/[^\d]/g, "")) || null : null;

	const cards: DumpCard[] = [];
	let i = 0;
	while (i < nodes.length) {
		const node = nodes[i];
		if (isStatus(node)) {
			const built = readCard(nodes, i + 1, node.text === "예약중");
			if (built.error) return { ok: false, error: built.error };
			if (built.card) cards.push(built.card);
			i = built.next;
			continue;
		}
		i += 1;
	}

	if (cards.length === 0) {
		return { ok: false, error: { kind: "no-sales", message: "판매중 카드를 못 읽었어요" } };
	}
	return { ok: true, cards: uniqueByTitle(cards), tabCount };
}

function readCard(
	nodes: Node[],
	start: number,
	reserved = false,
): { card: DumpCard | null; next: number; error?: DumpError } {
	let title = "";
	let titleNode: Node | null = null;
	let caption = "";
	let priceText = "";
	const stats: { n: number; x: number }[] = [];
	let i = start;
	while (i < nodes.length) {
		const node = nodes[i];
		if (isStatus(node)) break;
		// 숫자 뒤에 설명·가격이 또 오면 다음 카드다. 그 카드의 상태 글자가 화면 위 막대에 가려진 창에서 생긴다
		// (261105: 한 카드에 숫자 6개). 상태 글자 없는 카드는 이 창에서 건너뛰고 다음 창에서 읽는다.
		if (stats.length > 0 && (CAPTION.test(node.text) || PRICE.test(node.text))) break;
		if (node.desc === "끌어올리기" || node.desc === "홍보하기") {
			i += 1;
			break;
		}
		if (node.desc === "더보기" || node.desc === "추천받기" || node.desc === "닫기") {
			i += 1;
			continue;
		}
		if (node.text.includes("변경하기") || node.text.includes("판매 어시스턴트") || node.text.includes("판매 확률")) {
			i += 1;
			continue;
		}
		if (
			!title &&
			node.text &&
			!PRICE.test(node.text) &&
			!STAT.test(node.text) &&
			!CAPTION.test(node.text) &&
			node.text !== "글쓰기"
		) {
			title = node.text;
			titleNode = node;
			i += 1;
			continue;
		}
		if (title && !caption && CAPTION.test(node.text)) {
			caption = node.text;
			i += 1;
			continue;
		}
		if (title && !priceText && PRICE.test(node.text)) {
			priceText = node.text;
			i += 1;
			continue;
		}
		if (title && priceText && STAT.test(node.text)) {
			stats.push({ n: Number(node.text), x: node.x });
			i += 1;
			continue;
		}
		i += 1;
	}

	if (!title || !priceText) return { card: null, next: i };
	const counts = statsByIcons(stats.sort((a, b) => a.x - b.x).map((row) => row.n));
	if (!counts.ok) {
		return {
			card: null,
			next: i,
			error: { kind: "ambiguous-stats", message: counts.message, title },
		};
	}
	const meta = parseCaption(caption);
	return {
		card: {
			title,
			price: Number(priceText.replace(/[^\d]/g, "")),
			...meta,
			...counts.stats,
			reserved,
			photo: titleNode ? photoNearTitle(nodes, titleNode) : null,
		},
		next: i,
	};
}

function statsByIcons(
	nums: number[],
): { ok: true; stats: { views: number; chats: number; hearts: number } } | { ok: false; message: string } {
	if (nums.length === 0 || nums.length === 1) {
		return { ok: true, stats: { views: nums[0] ?? 0, chats: 0, hearts: 0 } };
	}
	// 2: 조회·관심. 3: 조회·채팅·관심. 실기에서 확인함.
	if (nums.length === 2) {
		return { ok: true, stats: { views: nums[0], chats: 0, hearts: nums[1] } };
	}
	if (nums.length === 3) {
		return { ok: true, stats: { views: nums[0], chats: nums[1], hearts: nums[2] } };
	}
	return {
		ok: false,
		message: `아이콘이 ${nums.length}개라 조회·채팅·관심을 나누지 않아요`,
	};
}

