/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes ?? (card.bumpAgoDays === null ? null : Math.round(card.bumpAgoDays * 1_440));
	if (minutes === null || !Number.isFinite(minutes)) return prior;
	return new Date(now - minutes * 60_000).toISOString();
}

edits.newText:
/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(
	card: DumpCard,
	prior: string | null,
	now: number,
	priorBumpCount: number | null = null,
): string | null {
	const minutes = card.bumpAgoMinutes ?? (card.bumpAgoDays === null ? null : Math.round(card.bumpAgoDays * 1_440));
	if (minutes === null || !Number.isFinite(minutes)) return prior;
	// 하루 단위 문구는 버킷이라, 그 버킷에 맞는 아는 시각이 있으면 더 정확한 그 시각을 지킨다.
	if (card.bumpAgoMinutes == null && card.bumpAgoDays !== null && prior !== null) {
		const priorMs = Date.parse(prior);
		const countsMatch =
			card.bumpCount == null || priorBumpCount == null || card.bumpCount === priorBumpCount;
		if (countsMatch && Number.isFinite(priorMs) && priorMs <= now) {
			const elapsedDays = Math.floor((now - priorMs) / 86_400_000);
			const candidateMs = now - card.bumpAgoDays * 86_400_000;
			const sameDay =
				new Date(priorMs).toISOString().slice(0, 10) === new Date(candidateMs).toISOString().slice(0, 10);
			const seoulDay = (ms: number) => new Date(ms + 9 * 3_600_000).toISOString().slice(0, 10);
			const sameSeoulDay = seoulDay(priorMs) === seoulDay(candidateMs);
			if (elapsedDays === card.bumpAgoDays || sameDay || sameSeoulDay) return prior;
		}
	}
	return new Date(now - minutes * 60_000).toISOString();
}

