	const priorEstimate =
		input.priorBumpedAt && input.priorBumpCount != null && input.priorBumpCount >= 1
			? estimateNextBumpAt(input.priorBumpedAt, input.priorBumpCount)
			: null;
	const priorIsEstimate = input.priorNext !== null && priorEstimate !== null && input.priorNext === priorEstimate;
	if (priorIsEstimate) return estimate;
	return laterOf(input.priorNext, estimate);
}

